<template><Card class="s1-ui"><header class="ui-header"><div><h2>商品与可售库存</h2><p>查看当前商品、经营状态及库存版本。库存由商户按原权限维护。</p></div></header><Form inline class="s2-query" @submit.native.prevent="search"><FormItem label="商品名称"><Input v-model="q" maxlength="60" clearable placeholder="输入商品名称" @on-enter="search"/></FormItem><FormItem label="所属店铺"><BusinessSelect v-model="targetStore" type="stores" :loader="stage2Stores" placeholder="按店铺名称搜索"/></FormItem><FormItem label="审核状态"><Select v-model="status" clearable><Option v-for="v in ['DRAFT','SUBMITTED','APPROVED','REJECTED']" :key="v" :value="v">{{label(v)}}</Option></Select></FormItem><FormItem label="上架状态"><Select v-model="marketStatus" clearable><Option value="UPPER">已上架</Option><Option value="DOWN">已下架</Option></Select></FormItem><FormItem label="库存状态"><Select v-model="stockState" clearable><Option value="IN_STOCK">有可售库存</Option><Option value="OUT_OF_STOCK">缺货</Option><Option value="INCOMPLETE">SKU资料不完整</Option></Select></FormItem><FormItem label="监管状态"><Select v-model="forced" clearable><Option value="true">监管下架</Option><Option value="false">未受管制</Option></Select></FormItem><Button type="primary" :loading="loading" @click="search">查询</Button><Button @click="reset">重置</Button></Form><Alert v-if="error" type="error" show-icon>{{error}} <Button type="text" @click="reload">重新读取</Button></Alert><div class="ui-table-scroll"><Table :data="records" :columns="columns" :loading="loading" no-data-text="当前条件下没有商品"><template slot="goods" slot-scope="{row}"><div class="s2-product"><ProductImage :goods-id="row.id" :file-id="row.galleryFileIds&&row.galleryFileIds[0]"/><div><strong>{{row.name||'未命名草稿'}}</strong><p>{{row.storeName||'店铺名称未提供'}}</p><p class="ui-meta">{{row.categoryPath||'类目未填写'}}</p></div></div></template><template slot="price" slot-scope="{row}">{{money(row.priceCent)}}</template><template slot="state" slot-scope="{row}"><StatusTag :value="row.reviewStatus"/><StatusTag :value="row.marketStatus"/><Tag v-if="row.forcedOff" color="red">监管下架</Tag><p>{{row.currentSaleable?'当前可售':'当前不可售'}} · {{label(row.stockState)}}</p></template><template slot="time" slot-scope="{row}">{{date(row.updatedAt)}}</template><template slot="operation" slot-scope="{row}"><Button size="small" @click="open(row)">查看详情</Button></template></Table></div><Page :total="total" :current="page" :page-size="size" show-total @on-change="turn"/></Card></template>
<script>
import {stage2UiRead,stage2Stores} from '@/api/stage2-ui';import {managerAccess} from '@/libs/manager-access';import {managerSession} from '@/libs/manager-session';import BusinessSelect from '../p0-stage1/usability/components/BusinessSelect';import BaseImage from '../p0-stage1/usability/components/ProductImage';import StatusTag from '../p0-stage1/usability/components/StatusTag';import {productImage} from './enabled';import {money,date,status as label} from '../p0-stage1/usability/display.cjs';import {restore,listQuery} from '../p0-stage1/usability/list-state.cjs';
const keys=['q','targetStore','status','marketStatus','stockState','forced'];
export default {components:{BusinessSelect,ProductImage:productImage(BaseImage),StatusTag},data(){return {...restore(this.$route.query,keys),records:[],total:0,loading:false,error:'',ticket:0,columns:[{title:'商品 / 店铺 / 类目',slot:'goods',minWidth:310},{title:'售价',slot:'price',minWidth:110},{title:'审核 / 销售 / 监管',slot:'state',minWidth:270},{title:'可售数量',key:'quantity',minWidth:100},{title:'更新（上海）',slot:'time',minWidth:170},{title:'操作',slot:'operation',width:110}]};},mounted(){this.reload();},beforeDestroy(){this.ticket++;},methods:{money,date,label,stage2Stores,async reload(){const ticket=++this.ticket,scope=managerSession.snapshot();this.loading=true;this.error='';try{const query=Object.fromEntries(keys.filter(k=>this[k]!=='').map(k=>[k,k==='forced'?this[k]==='true':this[k]]));const v=await stage2UiRead('',{...query,pageNumber:this.page,pageSize:this.size});if(ticket===this.ticket&&managerSession.sameSession(scope)){this.records=v.records;this.total=v.total;this.$nextTick(this.restoreScroll);}}catch(e){if(ticket===this.ticket){this.records=[];this.total=0;this.error=e.message;}}finally{if(ticket===this.ticket)this.loading=false;}},remember(){this.$router.replace({path:'/s1/goods',query:listQuery(this,keys)}).catch(()=>{});},search(){this.page=1;this.remember();this.reload();},reset(){for(const k of keys)this[k]='';this.search();},turn(page){this.page=page;this.remember();this.reload();},scrollKey(){return 's2-manager-goods-scroll:'+(managerAccess.state.info?.id||'unverified')+':'+JSON.stringify(listQuery(this,keys));},rememberScroll(){try{const container=document.querySelector('.single-page-con');sessionStorage.setItem(this.scrollKey(),JSON.stringify({container:container?.scrollTop||0,window:window.scrollY}));}catch(_){}},restoreScroll(){try{const value=JSON.parse(sessionStorage.getItem(this.scrollKey())||'null');if(!value)return;const container=document.querySelector('.single-page-con');if(container)container.scrollTop=value.container;window.scrollTo(0,value.window);}catch(_){}},open(row){this.rememberScroll();this.$router.push({path:'/s1/goods/'+row.id,query:listQuery(this,keys)});}}};
</script><style lang="scss">@import '../p0-stage1/usability/usability.scss';.s2-query{display:flex;flex-wrap:wrap;gap:8px;align-items:flex-start;margin:18px 0}.s2-query .ivu-form-item{width:210px;margin:0}.s2-query .ivu-form-item-content{line-height:normal}.s2-product{display:flex;gap:12px;align-items:center;padding:8px 0}.s2-product>div{min-width:0;overflow-wrap:anywhere}.s1-ui .ivu-page{margin-top:18px}</style>
